def longest_substring(s, chars):
    char_set = set(chars)
    substrings = s.split()
    valid_substrings = [substring for substring in substrings if all(char in char_set for char in substring)]
    if valid_substrings:
        return max(len(substring) for substring in valid_substrings)
    else:
        return 0

