import random

def play_game():
    options = ['камень', 'ножницы', 'бумага']
    computer_choice = random.choice(options)
    user_choice = input("Введите камень, ножницы или бумага: ")
    if user_choice == computer_choice:
        return "Ничья!"
    elif (user_choice == "камень" and computer_choice == "ножницы") or (user_choice == "ножницы" and computer_choice == "бумага") or (user_choice == "бумага" and computer_choice == "камень"):
        return "Вы победили! Компьютер выбрал " + computer_choice
    else:
        return "Вы проиграли! Компьютер выбрал " + computer_choice

if __name__ == '__main__':
    print(play_game())

